contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters to try calls as an arbitrary caller address and with arbitrary calldata/value
    // amount is Ether forwarded to Command or multiplicate; data for Command; target for Command; adr for multiplicate
    function run(address sender, address cmdTarget, bytes memory cmdData, address multTarget, uint amount) public payable {
        require(address(this).balance >= amount);

        // read initial observable state
        address ownerBefore = c.Owner();
        uint balBefore = address(c).balance;

        // Try withdraw() as this contract (which is the deployer of C) only if sender equals this contract
        // For generality, we interpret 'sender' parameter as desired caller: if sender == address(this) then the call should succeed (owner), else revert

        bool withdrewReverted;
        try c.withdraw{value: 0}() {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // Try Command call with provided value amount. We must ensure we have funds to forward
        bool cmdReverted;
        if (address(this).balance >= amount) {
            try c.Command{value: amount}(cmdTarget, cmdData) {
                cmdReverted = false;
            } catch {
                cmdReverted = true;
            }
        } else {
            // cannot perform the call due to lacking funds; mark as reverted to reflect it did not succeed
            cmdReverted = true;
        }

        // Try multiplicate forwarding amount to multTarget
        bool multReverted;
        if (address(this).balance >= amount) {
            try c.multiplicate{value: amount}(multTarget) {
                multReverted = false;
            } catch {
                multReverted = true;
            }
        } else {
            multReverted = true;
        }

        // read final observable state
        address ownerAfter = c.Owner();
        uint balAfter = address(c).balance;

        // Assert general rule: Owner address never changes; if withdraw or Command succeeded then caller must have been Owner (which is this contract since it deployed C), otherwise balance unchanged
        // Because InvMutTest deployed c, ownerBefore == address(this). We assert Owner is immutable and that non-owner successful calls cannot happen.

        // Build the assertion: Owner stays the same AND
        // if withdraw did NOT revert then ownerBefore must equal address(this) and the contract balance decreased (transfer) to 0 or decreased by some amount;
        // but because only owner may withdraw, we require that if withdraw succeeded then ownerBefore == address(this). Also Command only succeeds when ownerBefore == address(this).

        assert(
            ownerBefore == ownerAfter
            && (withdrewReverted || ownerBefore == address(this))
            && (cmdReverted || ownerBefore == address(this))
        );
    }

    receive() external payable {}
}

