contract InvMutTest {
    C c;
    address deployer;

    constructor(C _c) {
        c = _c;
        // record the deployer (Owner) of C as observed via the public getter
        deployer = c.Owner();
    }

    // single public test function: takes a caller address and attempts withdraw forwarded from this contract
    // We cannot change msg.sender for calls made from this contract, so we simulate two scenarios:
    // - If the provided caller equals deployer, the call should succeed (not revert).
    // - If the provided caller is different, the call invoked from this contract must revert and c balance must be unchanged.
    // To model calls from different senders, we forward through Command with data that triggers withdraw on C
    // but Command requires msg.sender == Owner, so only deployer can call Command successfully. That means
    // we cannot impersonate arbitrary addresses when calling c from this contract. Instead we assert the invariant
    // about direct calls: if this contract is the owner, withdraw must succeed; otherwise withdraw must revert and
    // balance must remain the same. The checker deploys c fresh where Owner == deployer recorded above.

    function run(address caller, uint sendAmount) public payable {
        require(address(this).balance >= sendAmount);

        // Observe balance before
        uint balBefore = address(c).balance;

        // Decide which external caller we are modeling: compare provided caller to recorded deployer
        bool callerIsOwner = (caller == deployer);

        // We will attempt to call withdraw via low-level call encoding so that the called function is withdraw()
        bytes memory withdrawSig = abi.encodeWithSignature("withdraw()");

        bool withdrewReverted;
        // When this test contract calls c.withdraw(), msg.sender == address(this). We assert behavior depending
        // on whether address(this) is the owner. But the general rule to prove: only the Owner may cause withdraw to succeed.
        // So if address(this) != Owner then withdraw must revert and balance unchanged. If address(this) == Owner it may succeed.
        // Determine if this contract equals the recorded deployer (Owner)
        bool thisIsOwner = (address(this) == deployer);

        // Attempt the call, forwarding sendAmount (withdraw is payable in contract P)
        // Keep the call top-level as required
        try c.Command{value: 0}(address(c), withdrawSig) {
            // If Command succeeds here it means this contract was Owner and was allowed to call Command which in turn calls withdraw on c
            // But Command itself requires msg.sender == Owner, so Command succeeding implies thisIsOwner true.
            withdrewReverted = false;
        } catch {
            // Command reverted. That could be due to not being owner; in that case withdraw was not executed.
            withdrewReverted = true;
        }

        uint balAfter = address(c).balance;

        // General rule asserted:
        // If this contract is the Owner, then the call may succeed (we do not demand it must), but if this contract is not Owner
        // then the attempt to invoke withdraw via Command must revert and the balance must remain unchanged.
        // Expressed: (thisIsOwner) || (withdrewReverted && balAfter == balBefore)
        assert(thisIsOwner || (withdrewReverted && balAfter == balBefore));
    }

    // receive to accept forwarded Ether if needed
    receive() external payable {}
}

