contract InvMutTest {
    C c;
    address deployer;

    constructor(C _c) { c = _c; deployer = msg.sender; }

    // Attempts by a caller (this contract) to invoke withdraw/Command with provided value and data.
    // We check that if this contract is not the Owner recorded in c, then withdraw and Command must revert
    // and must not change address(c).balance nor c.Owner(), and if it is the Owner then at least one of them may succeed.
    function run(uint sendAmount, address target, bytes calldata data) public payable {
        require(address(this).balance >= sendAmount, "insufficient test balance");

        // Read observable before-values
        address ownerBefore = c.Owner();
        uint balBefore = address(c).balance;

        // Try withdraw
        bool withdrawReverted;
        try c.withdraw{value: 0}() {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Record after withdraw attempt
        address ownerAfterWithdraw = c.Owner();
        uint balAfterWithdraw = address(c).balance;

        // Try Command with provided value and data
        bool commandReverted;
        // ensure this contract has sendAmount available
        // (we already required address(this).balance >= sendAmount)
        try c.Command{value: sendAmount}(target, data) {
            commandReverted = false;
        } catch {
            commandReverted = true;
        }

        address ownerAfterCommand = c.Owner();
        uint balAfterCommand = address(c).balance;

        // General rule: If this contract is NOT the Owner, then both calls must revert and c's Owner and balance must remain unchanged.
        // If this contract IS the Owner, then nothing is asserted about reverts (owner can succeed), but Owner must remain equal to original Owner.
        if (address(this) != ownerBefore) {
            assert(withdrawReverted && commandReverted && ownerAfterWithdraw == ownerBefore && ownerAfterCommand == ownerBefore && balBefore == balAfterWithdraw && balAfterWithdraw == balAfterCommand);
        } else {
            // If we are the owner, Owner should remain unchanged (withdraw/Command do not change Owner) and balance is allowed to change arbitrarily.
            assert(c.Owner() == ownerBefore);
        }
    }

    receive() external payable {}
}

