    function run(address payable funder, uint amount) public payable {
        // We will send `amount` ether into c by calling its receive fallback from this contract.
        // Ensure this contract has the funds to forward to c when needed.
        require(address(this).balance >= amount);

        // Observe initial Owner and balance
        address ownerBefore = c.Owner();
        uint balBefore = address(c).balance;

        // Fund c by calling its receive (send Ether to c). Use top-level call to address(c).
        // Note: this is not a call on c's typed interface, but is allowed to transfer Ether to c.
        (bool sent,) = address(c).call{value: amount}("");
        // require the funding succeeded so we can reason: if it fails then the after-state equals before-state
        if (!sent) {
            // if funding failed, then nothing changed; assert that property trivially holds: non-owner can't withdraw and owner withdraw would still leave c balance 0 change
            bool reverted;
            try c.withdraw() {
                reverted = false;
            } catch {
                reverted = true;
            }
            address ownerAfter = c.Owner();
            uint balAfter = address(c).balance;
            // If withdraw didn't revert then caller (this contract) must be Owner and balance becomes 0; otherwise state unchanged
            assert(ownerBefore == ownerAfter && (reverted || balAfter == 0));
            return;
        }

        // Now c has increased balance
        uint balFunded = address(c).balance;

        // Try calling withdraw as this contract (which is NOT necessarily Owner). Record revert.
        bool withdrewReverted;
        try c.withdraw() {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // Observe after-values
        address ownerAfter = c.Owner();
        uint balAfter = address(c).balance;

        // General rule:
        // - Owner never changes by withdraw
        // - If the call reverted then balance and owner remain as before
        // - If it succeeded then caller was Owner and c.balance is 0 afterwards
        assert(ownerBefore == ownerAfter && (withdrewReverted ? (balAfter == balFunded) : (balAfter == 0)));
    }

    receive() external payable {}
}

